package io.github.libtmux.scaladsl.cats

import _root_.cats.{Eq, Hash, Order, Show}
import io.github.libtmux.{PaneId, SessionId, TmuxVersion, WindowId}
import io.github.libtmux.scaladsl as direct

/** Instances derived from Java's `equals`/`hashCode`/`toString`, and from
  * `TmuxVersion`'s own `Comparable` — the one handle-adjacent type that
  * actually has a natural order. None of `Server`, `Session`, `Window`, `Pane`
  * or `Client` implements `Comparable` in Java, and none has a
  * domain-meaningful order (a pane's tmux index is not identity, and two panes
  * can share an index across different windows), so those get
  * `Eq`/`Show`/`Hash` only — never a manufactured `Order` that invites
  * `.sorted`/`SortedSet` producing an ordering nobody asked for.
  */
object Instances {

  /** `.equals`, not `==`: this runs for an unconstrained `A`, with no
    * `CanEqual[A, A]` in scope, and it is exactly the "trust me, this pair is
    * comparable" assertion `CanEqual.derived` makes for `==` itself — `.equals`
    * is the one operation `strictEquality` never restricts.
    */
  private def derived[A]: Eq[A] & Hash[A] & Show[A] = new Eq[A]
    with Hash[A]
    with Show[A] {
    def eqv(x: A, y: A): Boolean = x.equals(y)
    def hash(x: A): Int = x.hashCode()
    def show(x: A): String = x.toString
  }

  given serverInstances
      : (Eq[direct.Server] & Hash[direct.Server] & Show[direct.Server]) =
    derived
  given directSessionInstances
      : (Eq[direct.Session] & Hash[direct.Session] & Show[direct.Session]) =
    derived
  given directWindowInstances
      : (Eq[direct.Window] & Hash[direct.Window] & Show[direct.Window]) =
    derived
  given directPaneInstances
      : (Eq[direct.Pane] & Hash[direct.Pane] & Show[direct.Pane]) = derived
  given directClientInstances
      : (Eq[direct.Client] & Hash[direct.Client] & Show[direct.Client]) =
    derived

  given paneIdInstances: (Eq[PaneId] & Hash[PaneId] & Show[PaneId]) = derived
  given sessionIdInstances
      : (Eq[SessionId] & Hash[SessionId] & Show[SessionId]) = derived
  given windowIdInstances: (Eq[WindowId] & Hash[WindowId] & Show[WindowId]) =
    derived

  /** `TmuxVersion` already defines a natural order in Java (`implements
    * Comparable`); this is a direct projection of it, not a manufactured one.
    */
  given tmuxVersionInstances: (Order[TmuxVersion] & Show[TmuxVersion]) =
    new Order[TmuxVersion] with Show[TmuxVersion] {
      def compare(x: TmuxVersion, y: TmuxVersion): Int = x.compareTo(y)
      def show(x: TmuxVersion): String = x.toString
    }

  given sessionInstances[F[_]]
      : (Eq[Session[F]] & Hash[Session[F]] & Show[Session[F]]) =
    new Eq[Session[F]] with Hash[Session[F]] with Show[Session[F]] {
      def eqv(x: Session[F], y: Session[F]): Boolean =
        x.underlying == y.underlying
      def hash(x: Session[F]): Int = x.underlying.hashCode()
      def show(x: Session[F]): String = x.underlying.toString
    }

  given windowInstances[F[_]]
      : (Eq[Window[F]] & Hash[Window[F]] & Show[Window[F]]) =
    new Eq[Window[F]] with Hash[Window[F]] with Show[Window[F]] {
      def eqv(x: Window[F], y: Window[F]): Boolean =
        x.underlying == y.underlying
      def hash(x: Window[F]): Int = x.underlying.hashCode()
      def show(x: Window[F]): String = x.underlying.toString
    }

  given paneInstances[F[_]]: (Eq[Pane[F]] & Hash[Pane[F]] & Show[Pane[F]]) =
    new Eq[Pane[F]] with Hash[Pane[F]] with Show[Pane[F]] {
      def eqv(x: Pane[F], y: Pane[F]): Boolean = x.underlying == y.underlying
      def hash(x: Pane[F]): Int = x.underlying.hashCode()
      def show(x: Pane[F]): String = x.underlying.toString
    }

  given clientInstances[F[_]]
      : (Eq[Client[F]] & Hash[Client[F]] & Show[Client[F]]) =
    new Eq[Client[F]] with Hash[Client[F]] with Show[Client[F]] {
      def eqv(x: Client[F], y: Client[F]): Boolean =
        x.underlying == y.underlying
      def hash(x: Client[F]): Int = x.underlying.hashCode()
      def show(x: Client[F]): String = x.underlying.toString
    }
}

package io.github.libtmux.scaladsl.cats

import _root_.cats.effect.{Async, Deferred, Outcome, Resource}
import _root_.cats.effect.syntax.all._
import _root_.cats.syntax.all._
import fs2.concurrent.{Signal, SignallingRef}
import io.github.libtmux.snapshot.{ServerMirror => JavaServerMirror}
import java.time.Duration
import scala.jdk.OptionConverters._

/** Observe a tmux server through a continuously updated [[signal]].
  *
  * [[LiveServer.attach]] returns a `Resource` that closes the Java
  * [[io.github.libtmux.snapshot.ServerMirror ServerMirror]] when released. Read
  * [[failure]] to distinguish a quiet server from a stopped poller.
  */
final class LiveServer[F[_]] private (
    val signal: Signal[F, JavaServerMirror.View],
    private val outcomeD: Deferred[F, Either[Throwable, Unit]]
) {

  /** `None` while still live; `Some(cause)` once the background poller has
    * died. Never blocks.
    */
  def failure(implicit F: _root_.cats.Functor[F]): F[Option[Throwable]] =
    outcomeD.tryGet.map(_.flatMap(_.left.toOption))
}

object LiveServer {

  private val AwaitBudget: Duration = Duration.ofHours(24)

  /** Listens through a control client attached to `anchor`, rebuilding on every
    * announcement. The session is a required parameter: there is no arbitrary
    * pick left to make, and a session that later disappears is `ServerMirror`'s
    * own reconnect-or-`TargetGoneException` policy, surfaced through
    * [[LiveServer#failure]] like any other cause.
    */
  def attach[F[_]](
      anchor: Session[F]
  )(implicit F: Async[F]): Resource[F, LiveServer[F]] =
    for {
      mirror <- Resource.make(
        F.interruptible(JavaServerMirror.open(anchor.underlying.asJava))
      )(m => F.interruptible(m.close()))
      initial <- Resource.eval(F.delay(mirror.current()))
      ref <- Resource.eval(SignallingRef.of[F, JavaServerMirror.View](initial))
      outcomeD <- Resource.eval(Deferred[F, Either[Throwable, Unit]])
      _ <- pollLoop(mirror, ref, initial.epoch()).guaranteeCase {
        case Outcome.Succeeded(_) => outcomeD.complete(Right(())).void
        case Outcome.Errored(e)   => outcomeD.complete(Left(e)).void
        case Outcome.Canceled()   => outcomeD.complete(Right(())).void
      }.background
    } yield new LiveServer(ref, outcomeD)

  /** Waits from the epoch the signal was seeded with, not a second read of
    * `current()`: a view published between two reads would never reach the
    * signal.
    */
  private def pollLoop[F[_]](
      mirror: JavaServerMirror,
      ref: SignallingRef[F, JavaServerMirror.View],
      seeded: Long
  )(implicit
      F: Async[F]
  ): F[Unit] = {
    def step(epoch: Long): F[Unit] =
      F.interruptible(mirror.awaitNewer(epoch, AwaitBudget)).flatMap { newer =>
        newer.toScala match {
          case Some(view)             => ref.set(view) *> step(view.epoch())
          case None if mirror.isEnded =>
            mirror.cause().toScala.fold(F.unit)(F.raiseError)
          case None =>
            step(epoch) // AwaitBudget elapsed with no change; keep waiting.
        }
      }
    step(seeded)
  }
}

package io.github.libtmux.scaladsl.cats

import _root_.cats.effect.{Async, Resource}
import _root_.cats.syntax.all._
import fs2.Stream
import io.github.libtmux.control.{Delivery, EventSubscription}
import java.util.concurrent.atomic.AtomicBoolean
import scala.jdk.OptionConverters._

/** Pulls a bounded Java subscription with one active stream consumer. A full
  * buffer yields a `Delivery.Gap` in this stream before the events that remain.
  * FS2 demand does not provide tmux backpressure. A subscription does not
  * reconnect: attach again and read a snapshot.
  *
  * The stream itself suspends the *fiber*, not a platform thread, while idle:
  * [[io.github.libtmux.control.EventSubscription EventSubscription]] is already
  * single-consumer by construction at the Java layer, with a non-blocking
  * [[io.github.libtmux.control.EventSubscription#poll poll]] plus a one-shot
  * [[io.github.libtmux.control.EventSubscription#onReady onReady]] wakeup. Each
  * wait polls first — if something is already buffered, nothing suspends at all
  * — and only then arms `onReady`, disarming it with
  * [[io.github.libtmux.control.EventSubscription#clearReady clearReady]] if the
  * fiber is cancelled first. No `ExecutionContext` sized for blocking stream
  * reads is needed, because no read here ever blocks a thread.
  */
final class Observation[F[_], A] private[cats] (
    private[scaladsl] val underlying: EventSubscription[A],
    private val ownerClosed: AtomicBoolean
)(implicit F: Async[F]) {
  private val closed = new AtomicBoolean(false)
  private val reading = new AtomicBoolean(false)

  /** Waits for the fiber that owns [[stream]] to be woken, without blocking any
    * thread while idle. A cancelled wait disarms its own registration, so it
    * never fires after the fiber that was waiting on it is gone.
    */
  private val ready: F[Unit] = F.async[Unit] { wake =>
    F.delay {
      underlying.onReady(() => wake(Right(())))
      Some(F.delay(underlying.clearReady()))
    }
  }

  private def pull: F[Option[Delivery[A]]] =
    F.delay(underlying.poll()).flatMap { next =>
      if (next.isPresent) F.pure(Some(next.get))
      else if (!underlying.isClosed) ready >> pull
      else
        underlying.cause().toScala match {
          case Some(cause)                               => F.raiseError(cause)
          case None if closed.get() || ownerClosed.get() => F.pure(None)
          case None => F.raiseError(new Observation.UnknownCause())
        }
    }

  /** Reads on `F`'s own fiber scheduler. Cancelling the stream releases its
    * consumer slot and disarms any pending wakeup; releasing the observation
    * discards its buffered events. Deliberate closure ends the stream. A client
    * that ended the subscription fails it with that cause.
    */
  def stream: Stream[F, Delivery[A]] =
    Stream
      .bracket(F.delay {
        if (!reading.compareAndSet(false, true))
          throw new IllegalStateException(
            "an observation already has an active consumer"
          )
      })(_ => F.delay(reading.set(false)))
      .flatMap(_ => Stream.repeatEval(pull).unNoneTerminate)

  /** The cumulative overflow count. A `Delivery.Gap` in [[stream]] says where
    * it sits.
    */
  def droppedCount: F[Long] = F.delay(underlying.droppedCount())

  /** Reports subscription closure, including after resource finalization. */
  def isClosed: F[Boolean] = F.delay(underlying.isClosed())

  private[cats] def close: F[Unit] =
    F.delay(closed.set(true)) *> F.interruptible(underlying.close())
}

object Observation {

  /** The value inside an event delivery, and none for a gap. */
  def value[A](delivery: Delivery[A]): Option[A] = delivery match {
    case item: Delivery.Event[?] => Some(item.value().asInstanceOf[A])
    case _: Delivery.Gap[?]      => None
  }

  /** The event a strict reader kept. A gap fails the read. */
  def kept[A](delivery: Delivery[A]): A = delivery match {
    case item: Delivery.Event[?] => item.value().asInstanceOf[A]
    case gap: Delivery.Gap[?]    =>
      throw new IllegalStateException("lost " + gap.missed())
  }

  /** Java ended the subscription without exposing the reason. */
  final class UnknownCause private[cats] ()
      extends IllegalStateException(
        "control observation ended without a deliberate Scala close; Java exposes no cause"
      )

  private[cats] def resource[F[_]: Async, A](
      acquire: => EventSubscription[A],
      ownerClosed: AtomicBoolean
  ): Resource[F, Observation[F, A]] =
    Resource.make(Async[F].delay(new Observation[F, A](acquire, ownerClosed)))(
      _.close
    )
}

