/** A filter over `T`, both runnable and readable, opaque over Java's own
  * `FilterExpr[T]` — lossless by construction, the same reasoning
  * [[io.github.libtmux.scaladsl.Pane]] and its siblings rest on. `T` is the raw
  * Java handle type a Java field metamodel (`Pane_`, `Session_`, ...) is built
  * over, not this facade's opaque one: a query is a Java-shaped value that this
  * facade's own `.matching` extensions apply to captured Scala handles.
  */
opaque type Expr[T] = JavaFilterExpr[T]

object Expr {

  /** Wraps an existing Java expression, such as one a typed field method
    * already produced.
    */
  def apply[T](java: JavaFilterExpr[T]): Expr[T] = java

  // Nested, not top-level: extension-method implicit scope for Expr[X] only reaches Expr's own
  // companion (found regardless of the caller's package), never a plain top-level def in this
  // package — a caller outside io.github.libtmux.scaladsl.query, such as Pane.scala, would
  // otherwise need an explicit import for every one of these.
  extension [T](e: Expr[T]) {

    /** The underlying Java expression. Opaque wrapping is free, so this never
      * copies anything.
      */
    def asJava: JavaFilterExpr[T] = e

    def &&(other: Expr[T]): Expr[T] =
      (e: JavaFilterExpr[T]).and(other: JavaFilterExpr[T])
    def ||(other: Expr[T]): Expr[T] =
      (e: JavaFilterExpr[T]).or(other: JavaFilterExpr[T])
    def unary_! : Expr[T] = (e: JavaFilterExpr[T]).negate()

    /** `&&`, spelled out. */
    def and(other: Expr[T]): Expr[T] = e && other

    /** `||`, spelled out. */
    def or(other: Expr[T]): Expr[T] = e || other

    /** `unary_!`, spelled out. */
    def not: Expr[T] = !e

    /** Renders this expression as inspectable text. */
    def describe: String = (e: JavaFilterExpr[T]).describe()

    /** Evaluates this expression against one value, with no tmux I/O. */
    def matches(value: T): Boolean = (e: JavaFilterExpr[T]).test(value)
  }
}

package io.github.libtmux.scaladsl.query

import io.github.libtmux.{query => javaquery}
import java.util.regex.Pattern
import scala.jdk.CollectionConverters._

/** Typed field handles, wrapping Java's `io.github.libtmux.query.Fields`
  * records so every operator returns this facade's [[Expr]] rather than a raw
  * Java `FilterExpr`. An extension cannot reshape these methods' return type on
  * the Java records directly — same-named would silently lose to the Java
  * member, exactly the trap `-Werror` exists to catch — so each kind gets its
  * own small Scala class instead, one line per operator, forwarding to the Java
  * one underneath.
  */
object Fields {

  final class TextField[T] private[scaladsl] (
      private val java: javaquery.Fields.TextField[T]
  ) {
    def is(value: String): Expr[T] = Expr(java.is(value))
    def isNot(value: String): Expr[T] = Expr(java.isNot(value))
    def contains(value: String): Expr[T] = Expr(java.contains(value))
    def startsWith(value: String): Expr[T] = Expr(java.startsWith(value))
    def endsWith(value: String): Expr[T] = Expr(java.endsWith(value))
    def matches(value: Pattern): Expr[T] = Expr(java.matches(value))
    def in(values: Iterable[String]): Expr[T] = Expr(
      java.in(values.asJavaCollection)
    )
  }

  final class NumberField[T] private[scaladsl] (
      private val java: javaquery.Fields.NumberField[T]
  ) {
    def is(value: Int): Expr[T] = Expr(java.is(value))
    def isNot(value: Int): Expr[T] = Expr(java.isNot(value))
    def lessThan(value: Int): Expr[T] = Expr(java.lessThan(value))
    def atMost(value: Int): Expr[T] = Expr(java.atMost(value))
    def greaterThan(value: Int): Expr[T] = Expr(java.greaterThan(value))
    def atLeast(value: Int): Expr[T] = Expr(java.atLeast(value))
  }

  final class FlagField[T] private[scaladsl] (
      private val java: javaquery.Fields.FlagField[T]
  ) {
    def is(value: Boolean): Expr[T] = Expr(java.is(value))
    def isNot(value: Boolean): Expr[T] = Expr(java.isNot(value))
    def isTrue: Expr[T] = Expr(java.isTrue())
    def isFalse: Expr[T] = Expr(java.isFalse())
  }

  final class ToOneRef[T, R] private[scaladsl] (
      private val java: javaquery.Fields.ToOneRef[T, R]
  ) {
    def is(predicate: Expr[R]): Expr[T] = Expr(java.is(predicate.asJava))
  }

  final class ToManyRef[T, R] private[scaladsl] (
      private val java: javaquery.Fields.ToManyRef[T, R]
  ) {
    def any(predicate: Expr[R]): Expr[T] = Expr(java.any(predicate.asJava))
    def all(predicate: Expr[R]): Expr[T] = Expr(java.all(predicate.asJava))
    def none(predicate: Expr[R]): Expr[T] = Expr(java.none(predicate.asJava))
  }
}

package io.github.libtmux.scaladsl

import io.github.libtmux.{Server => JavaServer, ServerConfig}
import io.github.libtmux.control.ControlClient
import scala.concurrent.duration.FiniteDuration
import scala.jdk.DurationConverters._

/** The Java client, opaque: every member beyond
  * [[java.lang.AutoCloseable#close]] is an extension, generated from the
  * operation catalog or handwritten where the catalog marks it `WAIT`, `STREAM`
  * or `LIFECYCLE`. Closing an owned client releases its transport, not tmux;
  * `close()` comes from the `AutoCloseable` bound with no forwarding of its
  * own, so `Using.resource(server) { ... }` works.
  */
opaque type Server <: AutoCloseable = JavaServer

object Server {

  /** Opens an owned client for `config`. */
  def open(config: ServerConfig): Server = JavaServer.open(config)

  /** Borrows a Java client this facade did not open; closing it closes that
    * client too.
    */
  def fromJava(java: JavaServer): Server = java

  private[scaladsl] def wrap(java: JavaServer): Server = fromJava(java)

  given CanEqual[Server, Server] = CanEqual.derived

  // Nested, not top-level: a top-level `extension (self: Server) def asJava` in this file would
  // share a name with Session/Window/Pane/Client's own top-level `asJava`, and Scala 3 requires
  // same-named top-level definitions to share one compilation unit ("the same group of toplevel
  // definitions"). Nested here, it is found through Server's own extension-method implicit scope
  // instead, with no cross-file collision.
  extension (self: Server) {

    /** The underlying Java client. Opaque wrapping is free, so this never
      * copies scope or state.
      */
    def asJava: JavaServer = self

    /** This server with every command given `timeout` rather than the default,
      * sharing this one's transport and scope. `LIFECYCLE`, handwritten: not a
      * per-operation forward, a derived scope.
      */
    def within(timeout: FiniteDuration): Server =
      Server.wrap(self.asJava.within(timeout.toJava))

    /** A control-mode client on `session`, refused by a tmux other than the one
      * that captured it. `LIFECYCLE`, handwritten: resource scoping, not a
      * per-operation forward.
      */
    def control(session: Session): ControlClient =
      self.asJava.control(session.asJava)

    /** As [[control(session:io\.github\.libtmux\.scaladsl\.Session)* control]],
      * with an explicit attach timeout.
      */
    def control(session: Session, timeout: FiniteDuration): ControlClient =
      self.asJava.control(session.asJava, timeout.toJava)
  }
}

